import {parseCSV,platforms,types} from './core.js';
import {escapeHTML as esc} from './record-ui.js';
import {guessMapping,importLabels,parseImportRows,planImport,applyImport,changesForTarget} from './import-engine.js';
const names={new:'新增',update:'可更新',review:'需確認',unchanged:'無變更',invalid:'資料錯誤',duplicate:'檔內重複'};
const $=selector=>document.querySelector(selector);
const valueText=value=>Array.isArray(value)?`${value.length} 張 Drive 圖片`:value===undefined||value===''?'（空白）':String(value);
export function showImporter(api){
  const event=api.event;let rows=null,fileName='',plan=[],source=null,decisions={},draftId=crypto.randomUUID();
  const savedSources=()=>api.data().importSources?.filter(s=>s.eventId===event.id)||[];
  let selected=savedSources().at(-1)?.id||'new',draft={name:'',platform:'Threads',offset:'+08:00',defaultType:'對方來領取'},mapping={};
  function capture(){if(!$('#import-source'))return;selected=$('#import-source').value;draft={...draft,name:$('#source-name').value.trim(),platform:$('#source-platform').value,offset:$('#source-offset').value,defaultType:$('#source-type').value};if(rows){mapping={};document.querySelectorAll('[data-import-map]').forEach(select=>{if(select.value!=='')mapping[select.dataset.importMap]=Number(select.value)})}}
  function setup(loadSource=false){
    const existing=savedSources().find(s=>s.id===selected);if(loadSource&&existing)draft={...existing};
    api.open('匯入表單 CSV',`<p class="help">目標場次：${esc(event.name)}。重複更新請選同一個表單來源，檔名可不同。預覽前不會儲存資料或載入 Drive 圖片。</p><div class="form-grid"><label>表單來源<select id="import-source"><option value="new">建立新表單來源</option>${savedSources().map(s=>`<option value="${esc(s.id)}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>來源名稱 *<input id="source-name" maxlength="100" value="${esc(draft.name)}" placeholder="例如：米津應援無料登記"></label><label>未提供平台時使用<select id="source-platform">${platforms.map(p=>`<option ${p===draft.platform?'selected':''}>${p}</option>`).join('')}</select></label><label>提交時間的來源時區<select id="source-offset"><option value="+08:00" ${draft.offset==='+08:00'?'selected':''}>台灣 UTC+08:00</option><option value="+09:00" ${draft.offset==='+09:00'?'selected':''}>日本 UTC+09:00</option><option value="+00:00" ${draft.offset==='+00:00'?'selected':''}>UTC</option></select></label><label class="wide">未提供類型時使用<select id="source-type">${types.map(t=>`<option ${t===draft.defaultType?'selected':''}>${t}</option>`).join('')}</select></label></div><p class="help">「交換」自動轉為「互相交換」，「領取」轉為「對方來領取」。希望領取與實際交付分開保存。</p><input id="csv-file" type="file" accept=".csv,text/csv"><p class="help" id="import-file-name">${fileName?'已選檔案：'+esc(fileName):'選擇 Google 表單／試算表下載的 UTF-8 CSV。'}</p><div id="mapping-container"></div>`);
    $('#import-source').value=selected;
    $('#import-source').onchange=()=>{const choice=$('#import-source').value;capture();selected=choice;const saved=savedSources().find(s=>s.id===choice);if(saved){draft={...saved};if(rows)mapping=guessMapping(rows[0],saved.mapping)}else{draft={name:fileName.replace(/\.csv$/i,''),platform:'Threads',offset:'+08:00',defaultType:'對方來領取'};if(rows)mapping=guessMapping(rows[0])}setup()};
    $('#csv-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;capture();try{const parsed=parseCSV(await file.text());if(parsed.length<2)throw Error('CSV 至少需要標題與一筆資料');if(parsed.length>5001)throw Error('一次最多匯入 5,000 筆，請分批匯入');rows=parsed;fileName=file.name;if(!draft.name)draft.name=file.name.replace(/\.csv$/i,'');mapping=guessMapping(rows[0],savedSources().find(s=>s.id===selected)?.mapping);setup()}catch(error){api.toast(error.message)}};
    if(rows)mappingUI();
  }
  function mappingUI(){
    $('#mapping-container').innerHTML=`<h3>確認欄位對應</h3><p class="help">${rows.length-1} 筆資料。列序號預設忽略；時間戳記不會當成見面時間。「交換選項」只填希望領取，不自動分配無料。</p><div class="mapping">${Object.entries(importLabels).map(([key,label])=>`<label>${esc(label)}${key==='name'?' *':''}<select data-import-map="${key}"><option value="">不匯入</option>${rows[0].map((header,index)=>`<option value="${index}" ${mapping[key]===index?'selected':''}>${esc(header||'（無標題欄位）')}</option>`).join('')}</select></label>`).join('')}</div><p class="help">Drive 欄位可包含逗號或換行分隔的多個連結。匯入只保存連結，預覽時才連線 Google。</p><div class="form-actions"><button id="preview-import" class="primary">下一步：檢查差異</button></div>`;
    $('#preview-import').onclick=()=>{capture();if(!draft.name){api.toast('請填寫表單來源名稱');$('#source-name').focus();return}if(selected==='new'&&savedSources().some(s=>s.name.trim()===draft.name)){api.toast('此場次已有同名來源，請選取既有來源，或使用不同名稱。');return}source={...draft,id:selected==='new'?draftId:selected,eventId:event.id,mapping:Object.fromEntries(Object.keys(importLabels).map(key=>[key,mapping[key]===undefined?null:rows[0][mapping[key]]]))};try{const parsed=parseImportRows(rows,mapping,source);plan=planImport(api.data(),parsed,source);decisions=Object.fromEntries(plan.map(item=>[item.id,{action:item.action,targetId:item.targetId||'',fields:{}}]));review()}catch(error){api.toast(error.message)}};
  }
  function rowUI(item){
    const decision=decisions[item.id],locked=['unchanged','invalid','duplicate'].includes(item.category);
    const target=item.candidates.find(r=>r.id===decision.targetId),changes=target?changesForTarget(item,target,source):[];
    return `<details class="import-row" data-import-row="${item.id}" ${item.category==='review'?'open':''}><summary><span class="import-kind ${item.category}">${names[item.category]}</span><span>第 ${item.line} 列 · ${esc(item.values.name||'未填暱稱')}</span></summary><div class="import-row-content"><p class="help">${esc(item.reason)}</p>${item.warnings.map(w=>`<p class="warning">${esc(w)}</p>`).join('')}<div class="form-grid"><label>處理方式<select data-row-action="${item.id}">${locked?'<option value="skip">略過</option>':`<option value="">請選擇</option><option value="skip">略過，保持現況</option><option value="new">另建紀錄</option>${item.candidates.length?'<option value="merge">連結／更新既有紀錄</option>':''}`}</select></label>${item.candidates.length?`<label>目標紀錄<select data-row-target="${item.id}"><option value="">請選擇目標</option>${item.candidates.map(r=>`<option value="${esc(r.id)}" ${r.id===decision.targetId?'selected':''}>${esc(r.name)} · ${esc(r.platform||'未設定')} ${esc(r.account||'')} · ${esc(r.type)} · ${esc(r.status)}</option>`).join('')}</select></label>`:''}</div>${decision.action==='merge'&&target?`<p class="help">狀態、手動備註、時間地點與實際交付保留；採用空白值會清空該來源欄位。圖片合併不移除本機圖片。</p>${changes.length?changes.map(change=>`<div class="import-diff"><strong>${esc(importLabels[change.key]||change.key)}</strong><div class="import-diff-values"><div><small>目前</small><p>${esc(valueText(change.before))}</p></div><div><small>匯入</small><p>${esc(valueText(change.incoming))}</p></div></div>${change.locked?'<p class="help">保留現場整理資訊</p>':`<select aria-label="${esc(importLabels[change.key])}的更新方式" data-field-row="${item.id}" data-field-key="${change.key}"><option value="keep">保留目前內容</option><option value="incoming">採用匯入內容${change.incoming===''||Array.isArray(change.incoming)&&!change.incoming.length?'（清空）':''}</option>${['tags','driveImages'].includes(change.key)?'<option value="merge">合併並去重（不移除原項目）</option>':''}</select>`}</div>`).join(''):'<p class="help">內容相同，確認後只建立來源連結。</p>'}`:`<p class="help">${esc(item.values.platform||'未設定平台')} · ${esc(item.values.account||'未填帳號')} · ${esc(item.values.type||'')} · ${(item.values.driveImages||[]).length} 張 Drive 圖片連結</p>`}</div></details>`;
  }
  function review(){
    const counts=Object.fromEntries(Object.keys(names).map(key=>[key,plan.filter(item=>item.category===key).length]));
    api.open('檢查匯入差異',`<p class="help">${esc(event.name)}／${esc(source.name)}。所有變更在最後確認後一次儲存。</p><div class="import-summary">${Object.entries(names).map(([key,label])=>`<span>${label} ${counts[key]}</span>`).join('')}</div><div class="actions"><button id="skip-reviews">略過所有待確認</button><button id="link-unique">連結唯一相符紀錄（保留差異）</button></div><p class="help">沒有出現在 CSV 的紀錄不會刪除或取消。取消此視窗不會變更任何資料。</p><div id="import-plan">${plan.map(rowUI).join('')}</div><div class="form-actions"><button id="import-back">返回欄位設定</button><button class="primary" id="confirm-import">確認匯入</button></div>`);
    bindRows();$('#import-back').onclick=()=>setup();
    $('#skip-reviews').onclick=()=>{for(const item of plan)if(item.category==='review')decisions[item.id].action='skip';review()};
    $('#link-unique').onclick=()=>{for(const item of plan)if(item.category==='review'&&item.candidates.length===1){decisions[item.id].action='merge';decisions[item.id].targetId=item.candidates[0].id}review()};
    $('#confirm-import').onclick=async()=>{try{const result=applyImport(api.data(),plan,decisions,source);const c=result.counts;if(!confirm(`新增 ${c.added} 筆、更新／連結 ${c.updated} 筆、略過 ${c.skipped} 筆。確認匯入到「${event.name}」？`))return;const button=$('#confirm-import');button.disabled=true;api.busy(true);try{if(await api.commit(result.data)){api.close();api.after();api.toast(`新增 ${c.added} 筆、更新 ${c.updated} 筆、略過 ${c.skipped} 筆`)}}finally{api.busy(false);if(button.isConnected)button.disabled=false}}catch(error){api.toast(error.message)}};
  }
  function bindRows(){
    for(const item of plan){const decision=decisions[item.id],action=$(`[data-row-action="${item.id}"]`);action.value=decision.action;action.onchange=()=>{decision.action=action.value;updateRow(item)};
      const target=$(`[data-row-target="${item.id}"]`);if(target)target.onchange=()=>{decision.targetId=target.value;decision.fields={};updateRow(item)};
      const record=item.candidates.find(r=>r.id===decision.targetId);if(record)for(const change of changesForTarget(item,record,source)){const field=$(`[data-field-row="${item.id}"][data-field-key="${change.key}"]`);if(field){field.value=decision.fields[change.key]||change.choice;field.onchange=()=>decision.fields[change.key]=field.value}}
    }
  }
  function updateRow(item){const old=$(`[data-import-row="${item.id}"]`),expanded=old.open;old.outerHTML=rowUI(item);$(`[data-import-row="${item.id}"]`).open=expanded;bindRows()}
  setup(true);
}
